import React, { useEffect, useState } from "react";
import { auth } from "../firebase"; // Your Firebase client initialization
import { useNavigate } from "react-router-dom";
import NavBar from "../Components/NavBar"; 
import Footer from "../Components/Footer";

export default function AdminDashboard() {
  const [users, setUsers] = useState([]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [editingUser, setEditingUser] = useState(null);
  const [editEmail, setEditEmail] = useState("");
  const [editDisabled, setEditDisabled] = useState(false);

  const navigate = useNavigate();

  // Backend API base URL
  const API_BASE_URL = "http://localhost:5000";

  // Redirect if not admin
  useEffect(() => {
    const user = auth.currentUser;
    if (!user || user.email !== "yasasmigunasinghe@gmail.com") {
      navigate("/account");
    }
  }, [navigate]);

  // Fetch users from backend
  const fetchUsers = async () => {
    setLoading(true);
    setError("");
    try {
      const res = await fetch(`${API_BASE_URL}/users`);
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to fetch users: ${res.status} ${text}`);
      }
      const data = await res.json();
      setUsers(data);
    } catch (err) {
      setError(err.message);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  // Delete user by UID
  const handleDelete = async (uid) => {
    setError("");
    try {
      const res = await fetch(`${API_BASE_URL}/users/${uid}`, {
        method: "DELETE",
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to delete user: ${res.status} ${text}`);
      }
      fetchUsers();
    } catch (err) {
      setError(err.message);
    }
  };

  // Start editing a user row
  const startEdit = (user) => {
    setEditingUser(user);
    setEditEmail(user.email);
    setEditDisabled(user.disabled || false);
  };

  // Cancel editing
  const cancelEdit = () => {
    setEditingUser(null);
    setError("");
  };

  // Submit edited user data
  const submitEdit = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/users/${editingUser.uid}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: editEmail, disabled: editDisabled }),
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to update user: ${res.status} ${text}`);
      }
      setEditingUser(null);
      fetchUsers();
    } catch (err) {
      setError(err.message);
    }
  };

  return (
    <div style={{ padding: "20px" }}>
        <NavBar/>
      <h2>Admin User Management</h2>
      {error && <p style={{ color: "red", whiteSpace: "pre-wrap" }}>{error}</p>}
      {loading ? (
        <p>Loading users...</p>
      ) : (
        <table border="1" cellPadding="10" style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr>
              <th>UID</th>
              <th>Email</th>
              <th>Display Name</th>
              <th>Disabled</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {users.length === 0 ? (
              <tr><td colSpan="5" style={{ textAlign: "center" }}>No users found</td></tr>
            ) : (
              users.map((user) =>
                editingUser && editingUser.uid === user.uid ? (
                  <tr key={user.uid}>
                    <td>{user.uid}</td>
                    <td><input value={editEmail} onChange={(e) => setEditEmail(e.target.value)} /></td>
                    <td>{user.displayName || "-"}</td>
                    <td>
                      <input
                        type="checkbox"
                        checked={editDisabled}
                        onChange={(e) => setEditDisabled(e.target.checked)}
                      />
                    </td>
                    <td>
                      <button onClick={submitEdit} style={{ marginRight: 8 }}>Save</button>
                      <button onClick={cancelEdit}>Cancel</button>
                    </td>
                  </tr>
                ) : (
                  <tr key={user.uid}>
                    <td>{user.uid}</td>
                    <td>{user.email}</td>
                    <td>{user.displayName || "-"}</td>
                    <td>{user.disabled ? "Yes" : "No"}</td>
                    <td>
                      <button onClick={() => startEdit(user)} style={{ marginRight: 8 }}>Edit</button>
                      <button onClick={() => handleDelete(user.uid)} style={{ color: "red" }}>Delete</button>
                    </td>
                  </tr>
                )
              )
            )}
          </tbody>
        </table>
      )}
      <F/>
    </div>
  );
}
